+/// Bound output independently of the size advertised by an untrusted frame.
+pub(crate) fn zstd_decompress_bounded(data: &[u8], limit: usize) -> io::Result<Vec<u8>> {
+    let mut decoder = zstd::Decoder::new(data)
+        .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error))?;
+    // The storage encoder uses level one; its window fits in eight MiB.
+    // Larger admitted pages may need a correspondingly larger window.
+    decoder.window_log_max((usize::BITS - limit.saturating_sub(1).leading_zeros()).max(23))?;
+    let take = u64::try_from(limit)
+        .ok()
+        .and_then(|n| n.checked_add(1))
+        .ok_or_else(|| {
+            io::Error::new(io::ErrorKind::InvalidData, "decoded page budget overflow")
+        })?;
+    let mut output = Vec::new();
+    decoder
+        .take(take)
+        .read_to_end(&mut output)
+        .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error))?;
+    if output.len() > limit {
+        return Err(io::Error::new(
+            io::ErrorKind::InvalidData,
+            "decoded page exceeds its byte budget",
+        ));
+    }
+    Ok(output)
+}
+
+pub(crate) fn lz4_decompress_bounded(data: &[u8], limit: usize) -> io::Result<Vec<u8>> {
+    let size = data
+        .get(..4)
+        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "truncated LZ4 size"))?;
+    let size = u32::from_le_bytes([size[0], size[1], size[2], size[3]]) as usize;
+    if size > limit {
+        return Err(io::Error::new(
+            io::ErrorKind::InvalidData,
+            "decoded page exceeds its byte budget",
+        ));
+    }
+    lz4_decompress(data)
+}
